/**
 * Extract Manifest URL for Workflow 3
 * Accepts orderId (preferred) or manifestKey/manifestUrl from webhook.
 * Builds R2 manifestKey and a backend-proxied manifestUrl if needed.
 */
const input = $input.first().json || {};

const orderId = input.orderId || input.amazonOrderId || input.body?.orderId || input.body?.amazonOrderId;
const backendUrl = input.backendUrl || input.PUBLIC_BACKEND_URL || 'https://admin.littleherolabs.com';

let manifestKey = input.manifestKey || input.body?.manifestKey || null;
if (!manifestKey && orderId) {
  manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/2b-manifest.json`;
}

let manifestUrl = input.manifestUrl || input.body?.manifestUrl || null;
if (!manifestUrl && manifestKey) {
  manifestUrl = `${backendUrl}/api/manifests/${manifestKey}`;
}

if (!manifestKey || !manifestUrl) {
  throw new Error('Missing orderId or manifest info for Workflow 3');
}

return [{ json: { ...input, orderId, backendUrl, manifestKey, manifestUrl } }];

/**
 * Build Assembly Input From Manifest
 * Converts 2B manifest into the payload expected downstream.
 */
const input = $input.first().json || {};
const manifest = input || {}; // HTTP node passes manifest JSON as item

// Try to get preserved context from Extract node
let ctx = {};
try { ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {}; } catch {}

const order = manifest.order || {};
const entries = Array.isArray(manifest.entries) ? manifest.entries : [];
const amazonOrderId = order.amazonOrderId || ctx.orderId || null;
const characterHash = manifest.characterHash || order.characterHash || null;
const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';

if (!amazonOrderId || !characterHash) {
  throw new Error('Manifest missing amazonOrderId or characterHash');
}

const toProxy = (key) => `${backendUrl}/api/assets/${key}`;
const processedImages = entries
  .filter(e => Number.isFinite(Number(e.poseNumber)) && e.bgRemovedKey)
  .sort((a,b) => a.poseNumber - b.poseNumber)
  .map(e => ({
    poseNumber: e.poseNumber,
    fileName: (e.bgRemovedKey.split('/').pop()) || `pose${String(e.poseNumber).padStart(2,'0')}_nobg.png`,
    r2Path: e.bgRemovedKey,
    publicUrl: toProxy(e.bgRemovedKey),
    briaProcessed: true,
    briaStatus: 'COMPLETED',
    processingError: false,
  }));

return [{ json: {
  amazonOrderId,
  characterHash,
  characterSpecs: order.characterSpecs || {},
  bookSpecs: order.bookSpecs || {},
  orderDetails: order.orderDetails || {},
  publicR2Url: order.publicR2Url || null,
  processedImages
} }];

// Get order ready for book assembly (robust Webhook body handling)

// Webhook puts the real payload under .body; if not present, assume it's already flat
const input = $input.first().json;
const payload = input.body ?? input;

// Pull required fields from either flat or nested orderData
const amazonOrderId = payload.amazonOrderId ?? payload.orderData?.amazonOrderId ?? null;
const characterHash = payload.characterHash ?? payload.orderData?.characterHash ?? null;

// Optional sections
const characterSpecs = payload.characterSpecs ?? payload.orderData?.characterSpecs ?? {};
const bookSpecs      = payload.bookSpecs      ?? payload.orderData?.bookSpecs      ?? {};
const orderDetails   = payload.orderDetails   ?? payload.orderData?.orderDetails   ?? {};
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url    = payload.publicR2Url    ?? null;

// Processed images come in flat (2B sends them at top level)
const processedImages = payload.processedImages ?? [];

// Validate
if (!amazonOrderId || !characterHash) {
  throw new Error('Missing required order data: amazonOrderId or characterHash');
}
if (!Array.isArray(processedImages) || processedImages.length === 0) {
  throw new Error('No processed images received from Workflow 2B');
}

// Normalize/initialize assembly state
const assemblingOrder = {
  status: 'book_assembly_in_progress',
  assemblyStartedAt: new Date().toISOString(),
  pagesGenerated: 0,
  totalPagesRequired: 14,
  assemblyProgress: 0,

  amazonOrderId,
  characterHash,
  characterSpecs,
  bookSpecs,
  orderDetails,
  publicR2Url,

  processedImages
};

console.log(`Starting book assembly for order: ${amazonOrderId} (images: ${processedImages.length})`);
return [{ json: assemblingOrder }];

/**
 * Load Background Images (pages 1..14)
 * Uses shared publicR2Url. Backgrounds live at:
 *   .../book-mvp-simple-adventure/backgrounds/pageXX-<slug>.png
 */
const order = $input.first().json || {};
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;

if (!order.amazonOrderId) {
  throw new Error('Amazon Order ID is required for loading background images');
}

// Keep slugs in lockstep with your storage names.
const sceneSlugs = [
  'twilight-walk','night-forest','magic-doorway','courage-leap','morning-meadow',
  'tall-forest','mountain-vista','picnic-surprise','beach-discovery','crystal-cave',
  'giant-flowers','almost-there','animal-reveal','flying-home'
];
const sceneNames = [
  'twilight_walk','night_forest','magic_doorway','courage_leap','morning_meadow',
  'tall_forest','mountain_vista','picnic_surprise','beach_discovery','crystal_cave',
  'giant_flowers','enchanted_grove','animal_reveal','flying_home'
];

const backgroundImages = Array.from({ length: 14 }, (_, i) => {
  const pageNumber = i + 1;
  const imagePath = `${publicR2Url}/book-mvp-simple-adventure/backgrounds/page${String(pageNumber).padStart(2,'0')}-${sceneSlugs[i]}.png`;
  return {
    pageNumber,
    imagePath,
    sceneName: sceneNames[i],
    validated: false,
  };
});

return [{ json: { ...order, backgroundImages } }];

/**
 * Load story text (14 pages) + ensure characterImages exists
 * Belt-and-suspenders: synthesize from processedImages or canonical paths.
 */
const order = $input.first().json || {};
const childName = order.characterSpecs?.childName;
const hometown  = order.characterSpecs?.hometown || 'Seattle';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;
const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';

if (!childName) throw new Error('Child name required (characterSpecs.childName)');
const hash = order.characterHash || order.orderData?.characterHash;
if (!hash) throw new Error('Missing characterHash in order payload');

// 1) Story lines (unchanged)
const lines = [
  `It was a nice night in ${hometown}. ${childName} went outside.`,
  `${childName} looked at the stars.<br>You like to explore, the voice said.`,
  `There was a doorway! ${childName} walked through.`,
  `Stars were all around! ${childName} felt brave.`,
  `${childName} noticed footprints and followed them.`,
  `The path went through giant trees. ${childName} felt small, but not scared.`,
  `Look how far you came, the voice said.`,
  `Lunch was waiting! ${childName} ate happily.<br>You earned this, the voice said.`,
  `The path became warm sand. Look down there, the voice said.<br>${childName} found a beautiful shell!`,
  `${childName} found a cave with sparkly crystals! They glowed with rainbow colors. You can find beauty everywhere, the voice said.`,
  `The path went through giant flowers. The petals were SO big!<br>You make others happy, the voice said.`,
  `The voice felt very close now. You are perfect just as you are, it said.<br>${childName} looked around. Where was the voice?`,
  `Tiger appeared! It was the voice!<br>I have been with you this whole time, said Tiger.`,
  `Ready to fly home? asked Tiger. They flew through the stars to ${hometown}.<br>I am always in your heart, said Tiger.`
];

const storyTexts = lines.map((text, i) => ({
  pageNumber: i + 1,
  text,
  characterName: childName,
  hometown,
  validated: true,
}));

// 2) Pose name map (for HTML alt/fallbacks)
const poseNames = [
  'walking',                 // 1
  'walking-looking-higher',  // 2
  'looking',                 // 3
  'floating',                // 4
  'walking-looking-down',    // 5
  'jogging',                 // 6
  'looking',                 // 7
  'sitting-eating',          // 8
  'crouching',               // 9
  'crawling-moving-happy',   // 10
  'surprised-looking-up',    // 11
  'surprised'                // 12
];

// 3) Ensure processedImages exists (12 canonical _nobg files) if missing
let processedImages = Array.isArray(order.processedImages) && order.processedImages.length
  ? order.processedImages
  : Array.from({ length: 12 }, (_, i) => {
      const poseNumber = i + 1;
      const padded = String(poseNumber).padStart(2, '0');
      const fileName = `characters_${hash}_pose${padded}_nobg.png`;
      const r2Path = `${BASE_PREFIX}/${hash}/${fileName}`;
      const publicUrl = `${publicR2Url}/${r2Path}`;
      return {
        poseNumber,
        fileName,
        r2Path,
        publicUrl,
        briaProcessed: true,
        briaStatus: 'COMPLETED',
        processingError: false,
      };
    });

// 4) Ensure characterImages exists; build it from processedImages if needed
if (!order.characterImages || !Array.isArray(order.characterImages.poses)) {
  const poses = processedImages
    .filter(pi => Number.isFinite(pi.poseNumber) && pi.poseNumber >= 1 && pi.poseNumber <= 12)
    .sort((a, b) => a.poseNumber - b.poseNumber)
    .map(pi => ({
      poseNumber: pi.poseNumber,
      poseFilename: poseNames[pi.poseNumber - 1] || `pose${String(pi.poseNumber).padStart(2, '0')}`,
      imagePath: pi.publicUrl,
      pageNumber: pi.poseNumber,    // 1..12 map to pages 1..12
      validated: !pi.processingError,
    }));

  order.characterImages = {
    base: `${publicR2Url}/${BASE_PREFIX}/${hash}/base-character.png`,
    poses,
  };
}

// 5) Return merged payload for HTML node
return [{
  json: {
    ...order,
    publicR2Url,
    storyTexts,
    processedImages,
  }
}];

// Build only the page blocks for PDFMonkey {{ pages_html }}
const order = $input.first().json;

// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;
// UPDATE: Removed hardcoded TEXT_BG and FONT_URL construction - use backend signed URL API if needed
// Note: These may need to be generated via signed URL API before PDF generation
const TEXT_BG  = null; // Will need signed URL if PDF service requires external access
const FONT_URL = null; // Will need signed URL if PDF service requires external access

// helpers
const findBg   = (i) => order.backgroundImages?.find(b => b.pageNumber === i)?.imagePath || '';
const findTxt  = (i) => (order.storyTexts?.find(s => s.pageNumber === i)?.text || '').replace(/\n/g,'<br>');

// Pose lookup (no character on page 13; page 14 fallback to any "flying")
const findPose = (i) => {
  if (i === 13) return null; // SPEC: page 13 has animal only
  const poses = order.characterImages?.poses || [];
  let p = poses.find(p => p.pageNumber === i);
  if (!p && i === 14) p = poses.find(p => /fly|flying/i.test(p.filename || p.pose || ''));
  return p || poses[0] || null;
};

// px→in at 300dpi
const px2in = (px) => (px / 300).toFixed(4) + 'in';

// Original px map (absolute) for most pages
const CHAR = {
  1:  { left:1453, top:1938, w: 900, flip:  1 },
  2:  { left:1403, top:2091, w: 950, flip:  1 },
  3:  { left:1275, top:2295, w: 900, flip:  1 },   // will be overridden
  4:  { left:1020, top:2142, w:1100, flip: -1 },   // will be overridden
  5:  { left:1250, top:2066, w: 900, flip: -1 },
  6:  { left:1326, top:2066, w: 900, flip:  1 },
  7:  { left:1199, top:1683, w: 900, flip: -1 },
  8:  { left:1453, top:2040, w:1400, flip:  1 },
  9:  { left:1428, top:2142, w:1100, flip: -1 },
  10: { left:1275, top:2295, w:1300, flip: -1 },
  11: { left:1964, top:2117, w: 500, flip:  1 },
  12: { left: 893, top:2142, w:1000, flip: -1 },
  // 13: no character
  14: { left: 893, top:1836, w:1500, flip:  1 },   // will be overridden w/ same numbers + class sprite
};

// === OVERRIDES from your snippet (absolute px, bottom-center anchor) ===
// page03
const OV3 = { left:1020, top:2142, w:1100, flip:-1, rotate:0 };
// page04
const OV4 = { left:1530, top:1734, w:1100, flip: 1, rotate:-20 };
// page14 (character)
const OV14C = { left:893, top:1836, w:1500, flip:1, rotate:0 };
// page14 (animal)
const OV14A = { left:1275, top:1964, w:1250 };

function charStyle(n){
  // apply overrides first
  if (n === 3) {
    return [
      `left:${px2in(OV3.left)}`,
      `top:${px2in(OV3.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV3.flip})`,
      `width:${px2in(OV3.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  if (n === 4) {
    return [
      `left:${px2in(OV4.left)}`,
      `top:${px2in(OV4.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV4.flip}) rotate(-20deg)`,
      `width:${px2in(OV4.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  if (n === 14) {
    return [
      `left:${px2in(OV14C.left)}`,
      `top:${px2in(OV14C.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV14C.flip})`,
      `width:${px2in(OV14C.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  // fallback to your original px map (converted) for other pages
  const c = CHAR[n];
  if (!c) return '';
  return [
    `left:${px2in(c.left)}`,
    `top:${px2in(c.top)}`,
    `transform:translate(-50%,-100%) scaleX(${c.flip})`,
    `width:${px2in(c.w)}`,
    `z-index:11`
  ].join('; ') + ';';
}

// Animals
// Animals (URLs fixed). Page 13: animal only with tuned placement. Page 14: from doc.
function animalHTML(i){
  if (i === 13) {
    const src = `${publicR2Url}/book-mvp-simple-adventure/characters/animals/tiger-appears.png`;

    // Tuned for PDFMonkey with bottom-center anchor:
    // - Slightly right of center (≈ 65%)
    // - A bit higher (≈ 74%)
    // - Large reveal (≈ 6.0in wide)
    const leftPx = 1650;    // ≈ 65% of 2550
    const topPx  = 1900;    // ≈ 74% of 2550
    const wPx    = 1800;    // ≈ 6.0in at 300dpi

    return `
      <div class="animal" style="
        left:${px2in(leftPx)};
        top:${px2in(topPx)};
        transform:translate(-50%,-100%);
        width:${px2in(wPx)};
        z-index:9;">
        <img class="sprite" src="${src}" alt="Tiger Appears">
      </div>`;
  }

  if (i === 14) {
    const src = `${publicR2Url}/book-mvp-simple-adventure/characters/animals/tiger-flying.png`;
    // From positioning doc
    const left = px2in(1275), top = px2in(1964), w = px2in(1250);
    return `
      <div class="animal" style="
        left:${left};
        top:${top};
        transform:translate(-50%,-100%);
        width:${w};
        z-index:9;">
        <img class="sprite" src="${src}" alt="Tiger Flying">
      </div>`;
  }
  return '';
}


// Inline font so it applies even when only {{ pages_html }} is rendered
const fontStyle = `
<style>
@font-face {
  font-family: 'CustomBook';
  src: url('${FONT_URL}') format('truetype');
  font-display: swap;
}
.text-content, body { font-family: 'CustomBook', Arial, sans-serif; }
</style>`.trim();

let pages_html = fontStyle + '\n';

for (let i = 1; i <= 14; i++) {
  const bg   = findBg(i);
  const pose = findPose(i);
  const text = findTxt(i);

  pages_html += `
<div class="book-page" id="page-${i}">
  <div class="page-bg" style="background-image:url('${bg}');"></div>

  <div class="text-box" style="background-image:url('${TEXT_BG}')">
    <div class="text-content">${text}</div>
  </div>

  ${pose ? `<div class="character" style="${charStyle(i)}"><img class="sprite" src="${pose.imagePath}" alt=""></div>` : ''}
  ${animalHTML(i)}
</div>`;
}

return [{
  json: {
    ...order,
    pages_html,
    pdfMonkeyTemplateId: order.pdfMonkeyTemplateId || '5539ddb4-ec78-4ae9-a3fb-db1e7f8dd172',
    pdfFilename: `complete_book_${order.amazonOrderId || 'ORDER'}.pdf`,
  }
}];

const d = $input.first().json;

return [{
  json: {
    document: {
      document_template_id: d.pdfMonkeyTemplateId,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: {
        pages_html: d.pages_html
      }
    }
  }
}];

const order = $input.first().json;
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;

const completed = {
  ...order,
  status: 'book_assembly_completed',
  bookAssemblyCompletedAt: new Date().toISOString(),
  finalBookUrl: `${publicR2Url}/little-hero-orders/${order.amazonOrderId}/${order.pdfFilename}`,
  totalAssemblyTime: order.assemblyStartedAt ? (new Date() - new Date(order.assemblyStartedAt)) : null,
  averageTimePerPage: order.assemblyStartedAt
    ? Math.round(((new Date() - new Date(order.assemblyStartedAt)) / (order.totalPagesRequired || 14)) / 1000)
    : null
};

console.log(`Book assembly completed: ${order.amazonOrderId}`);
return [{ json: completed }];

const order = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  workflow: '3-book-assembly-voice-of-wonder',
  orderId: order.amazonOrderId,
  status: order.status,
  pagesGenerated: order.pagesGenerated,
  totalPagesRequired: order.totalPagesRequired,
  assemblyProgress: order.assemblyProgress,
  finalBookUrl: order.finalBookUrl || 'N/A'
};

console.log('Book Assembly Results:', JSON.stringify(logEntry, null, 2));
return [{ json: logEntry }];

// Poll PDFMonkey until the document is ready; max 30s
// Also MERGE with Prepare PDFMonkey Data so we keep amazonOrderId/pdfFilename/etc.
const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;

if (!docId) {
  throw new Error('PDFMonkey create response missing id');
}

const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const http = this.helpers.httpRequest;

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;

async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 15) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method: 'GET', url: apiBase + docId, json: true });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++;
  await sleep(2000);
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey document not ready after polling (status=${status})`);
}

// Merge in the context from Prepare PDFMonkey Data
let ctx = {};
try {
  ctx = $items('Prepare PDFMonkey Data', 0, 0)?.[0]?.json || {};
} catch {}

return [{
  json: {
    ...ctx,
    pdfMonkeyDocumentId: docId,
    pdfDownloadUrl: downloadUrl
  }
}];

// Load story text for all pages with personalization + animal images
const order = $input.first().json || {};
const childName = order.characterSpecs?.childName;
const hometown  = order.characterSpecs?.hometown || 'Seattle';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;

if (!childName) throw new Error('Child name required (characterSpecs.childName)');

// --- Normalize & map animal guide ---
const rawAnimalInput = String(order.characterSpecs?.animalGuide || 'tiger');

// strip emojis/punctuation, normalize spaces/hyphens, lowercase
const cleaned = rawAnimalInput
  .replace(/[^a-z0-9\s-]/gi, '')   // drop emojis & punctuation
  .replace(/\s+/g, ' ')            // collapse spaces
  .trim()
  .toLowerCase();

// alias map → slug we use in filenames
const ALIAS_TO_SLUG = {
  'dog': 'dog',
  'cat': 'cat',
  't rex': 't-rex',
  'trex': 't-rex',
  't-rex': 't-rex',
  'unicorn': 'unicorn',
  'tiger': 'tiger',
  'lion': 'lion',
  'owl': 'owl',
};

// default to tiger if unknown
const animalSlug = ALIAS_TO_SLUG[cleaned] || 'tiger';

// pretty display names for alt text, etc.
const SLUG_TO_DISPLAY = {
  'dog': 'Dog',
  'cat': 'Cat',
  't-rex': 'T-Rex',
  'unicorn': 'Unicorn',
  'tiger': 'Tiger',
  'lion': 'Lion',
  'owl': 'Owl',
};
const animalDisplayName = SLUG_TO_DISPLAY[animalSlug] || 'Tiger';

// build URLs (you said animals live at /animals/)
const animalImages = {
  appears: `${publicR2Url}/animals/${animalSlug}-appears.png`,
  flying:  `${publicR2Url}/animals/${animalSlug}-flying.png`,
};

// --- Story text (unchanged) ---
const lines = [
  `It was a nice night in ${hometown}. ${childName} went outside.`,
  `${childName} looked at the stars.<br>You like to explore, the voice said.`,
  `There was a doorway! ${childName} walked through.`,
  `Stars were all around! ${childName} felt brave.`,
  `${childName} noticed footprints and followed them.`,
  `The path went through giant trees. ${childName} felt small, but not scared.`,
  `Look how far you came, the voice said.`,
  `Lunch was waiting! ${childName} ate happily.<br>You earned this, the voice said.`,
  `The path became warm sand. Look down there, the voice said.<br>${childName} found a beautiful shell!`,
  `${childName} found a cave with sparkly crystals! They glowed with rainbow colors. You can find beauty everywhere, the voice said.`,
  `The path went through giant flowers. The petals were SO big!<br>You make others happy, the voice said.`,
  `The voice felt very close now. You are perfect just as you are, it said.<br>${childName} looked around. Where was the voice?`,
  `${animalDisplayName} appeared! It was the voice!<br>I have been with you this whole time, said ${animalDisplayName}.`,
  `Ready to fly home? asked ${animalDisplayName}. They flew through the stars to ${hometown}.<br>I am always in your heart, said ${animalDisplayName}.`
];

const storyTexts = lines.map((text, i) => ({
  pageNumber: i + 1, text, characterName: childName, hometown, validated: true
}));

return [{
  json: {
    ...order,
    publicR2Url,
    animalImages,          // ← add
    animalDisplayName,     // ← optional, nice for alt text
    storyTexts
  }
}];

// Build a standalone preview HTML you can open anywhere
const order = $input.first().json;

const page_css   = order.page_css || '';
const pages_html = order.pages_html || '';

const html = [
  '<!doctype html>',
  '<html>',
  '<head>',
  '<meta charset="utf-8">',
  '<title>Book Preview</title>',
  '<style>',
  page_css,
  '</style>',
  '</head>',
  '<body>',
  // visible banner so you know CSS applied
  '<div style="position:relative;z-index:9999;padding:.25in;background:#ff0;color:#000;font:bold 14pt/1.2 system-ui, -apple-system, Segoe UI, Roboto, sans-serif">',
  'BROWSER PREVIEW — if you see this bar, CSS applied',
  '</div>',
  pages_html,
  '</body>',
  '</html>'
].join('\n');

const buf = Buffer.from(html, 'utf8');

// 1) Binary (works with Write Binary File or the node's Download button)
const binary = {
  file: {
    data: buf,
    mimeType: 'text/html',
    fileName: `book-preview_${order.amazonOrderId || 'ORDER'}.html`,
  }
};

// 2) Data URL (paste this into your browser if Download doesn't work)
const dataUrl = 'data:text/html;charset=utf-8,' + encodeURIComponent(html);

// 3) Inline string (copy-paste into a local .html)
